"""Original offline state models; no live Nexus calls or simulated success claims."""

def step(title, explanation, actor, focus, active, states, field):
    name, before, after, why = field
    return dict(title=title, explanation=explanation, actor=actor, focus=focus,
                active=active, states=states,
                fields=[dict(name=name, before=before, after=after, why=why)],
                bands=[dict(label=name, value=after, detail=why)])


def diagram(identifier, chapter, title, intro, assumptions, nodes, edges, steps, marker):
    return dict(id=identifier, volume='nexus', chapter=chapter, anchor=chapter,
                title=title, intro=intro, assumptions=assumptions, insert_before=marker,
                nodes=[dict(id=i, label=label, sub=sub) for i,label,sub in nodes],
                edges=[dict(id=i, **{'from':a,'to':b}, label=label) for i,a,b,label in edges], steps=steps)


